<?php
require_once __DIR__ . '/includes/auth.php'; require_login(); require_once __DIR__ . '/includes/mailer.php'; if(current_user()['role']!=='resident'){redirect('index.php');}$pdo=db();
$stmt=$pdo->prepare('SELECT r.*,u.account_expires_at FROM residents r JOIN users u ON u.resident_id=r.id WHERE u.id=?');$stmt->execute([current_user()['id']]);$resident=$stmt->fetch();if(!$resident){session_destroy();redirect('login.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['form_action']??'';if($action==='document'){$fees=['Barangay clearance'=>50,'Certificate of residency'=>30,'Certificate of indigency'=>0,'Business clearance'=>100,'Special certification'=>30];$type=$_POST['document_type'];$no='REQ-'.date('Y').'-'.str_pad((string)random_int(1,999999),6,'0',STR_PAD_LEFT);$pdo->prepare('INSERT INTO document_requests (resident_id,request_no,document_type,requester_name,purpose,fee,status) VALUES (?,?,?,?,?,?,\'Pending\')')->execute([$resident['id'],$no,$type,$resident['full_name'],trim($_POST['purpose']),$fees[$type]??0]);$requestId=(int)$pdo->lastInsertId();notify_staff('New document request',$resident['full_name'].' submitted '.$type,'documents.php');if(!empty($_FILES['attachment']['name'])){if($path=secure_upload($_FILES['attachment'],'attachments'))$pdo->prepare('INSERT INTO attachments (uploaded_by,entity,entity_id,original_name,stored_path,mime_type,file_size) VALUES (?,?,?,?,?,?,?)')->execute([current_user()['id'],'document_request',$requestId,$_FILES['attachment']['name'],$path,$_FILES['attachment']['type'],(int)$_FILES['attachment']['size']]);audit_action('attachment_uploaded','document_requests',$requestId,$_FILES['attachment']['name']);}send_notification(mail_setting('MAIL_FROM_EMAIL',MAIL_FROM_EMAIL),'New resident document request','<p>'.h($resident['full_name']).' submitted a '.h($type).' request. Request number: <strong>'.h($no).'</strong>.</p>');flash('success','Your document request was submitted. Track it in Documents.');redirect('resident_portal.php?tab=documents');}if($action==='incident'){$case='BLT-'.date('Y').'-'.str_pad((string)random_int(1,9999),4,'0',STR_PAD_LEFT);$reportType=trim($_POST['report_type']);$pdo->prepare('INSERT INTO blotters (resident_id,case_no,report_type,incident_type,complainant,respondent,location,incident_date,narrative,status,priority) VALUES (?,?,?,?,?,?,?, ?,? ,\'Recorded\',\'Normal\')')->execute([$resident['id'],$case,$reportType,$reportType,$resident['full_name'],trim($_POST['respondent']),trim($_POST['location']),str_replace('T',' ', $_POST['incident_date']),trim($_POST['narrative'])]);$incidentId=(int)$pdo->lastInsertId();notify_staff('New issue report',$resident['full_name'].' submitted '.$reportType.' case '.$case,'blotters.php');if(!empty($_FILES['attachment']['name'])){if($path=secure_upload($_FILES['attachment'],'attachments'))$pdo->prepare('INSERT INTO attachments (uploaded_by,entity,entity_id,original_name,stored_path,mime_type,file_size) VALUES (?,?,?,?,?,?,?)')->execute([current_user()['id'],'blotter',$incidentId,$_FILES['attachment']['name'],$path,$_FILES['attachment']['type'],(int)$_FILES['attachment']['size']]);audit_action('attachment_uploaded','blotters',$incidentId,$_FILES['attachment']['name']);}send_notification(mail_setting('MAIL_FROM_EMAIL',MAIL_FROM_EMAIL),'New resident report','<p>'.h($resident['full_name']).' submitted a '.h($reportType).' with case number <strong>'.h($case).'</strong>.</p>');flash('success','Your report was recorded. Track it in Report an issue.');redirect('resident_portal.php?tab=report');}if($action==='feedback'){$rating=(int)($_POST['rating']??0);$pdo->prepare('INSERT INTO feedback (resident_id,category,rating,message) VALUES (?,?,?,?)')->execute([$resident['id'],trim($_POST['category']),$rating?:null,trim($_POST['message'])]);notify_staff('New resident feedback',$resident['full_name'].' submitted '.trim($_POST['category']).' feedback','feedback.php');flash('success','Thank you. Your feedback was sent to the barangay desk.');redirect('resident_portal.php?tab=feedback');}}
$tab=$_GET['tab']??'documents';if(!in_array($tab,['documents','report','feedback','announcements'],true))$tab='documents';$documents=$pdo->prepare('SELECT * FROM document_requests WHERE resident_id=? ORDER BY requested_at DESC');$documents->execute([$resident['id']]);$documents=$documents->fetchAll();$incidents=$pdo->prepare('SELECT * FROM blotters WHERE resident_id=? ORDER BY incident_date DESC');$incidents->execute([$resident['id']]);$incidents=$incidents->fetchAll();$feedback=$pdo->prepare('SELECT * FROM feedback WHERE resident_id=? ORDER BY created_at DESC');$feedback->execute([$resident['id']]);$feedback=$feedback->fetchAll();$announcements=$pdo->query('SELECT * FROM announcements WHERE is_published=1 ORDER BY published_at DESC LIMIT 10')->fetchAll();$pageTitle='My resident portal';$activePage='portal';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Resident portal / My services</div><h1>Hello, <?= h(explode(' ',trim($resident['full_name']))[0]) ?>.</h1><p>Use the separate service tabs to request documents, report issues, send feedback, and read barangay announcements.</p></div><a class="secondary-button" href="logout.php">Sign out</a></section><div class="stats-grid"><div class="stat-card"><div class="stat-icon blue">♙</div><span class="stat-label">Barangay ID</span><strong class="small-value"><?= h($resident['barangay_id']) ?></strong><small><?= h($resident['status']) ?></small></div><div class="stat-card"><div class="stat-icon mint">▤</div><span class="stat-label">My document requests</span><strong><?= count($documents) ?></strong><small>Track release status</small></div><div class="stat-card"><div class="stat-icon amber">▣</div><span class="stat-label">My reports</span><strong><?= count($incidents) ?></strong><small>Track case updates</small></div><div class="stat-card"><div class="stat-icon violet">◷</div><span class="stat-label">Portal access until</span><strong class="small-value"><?= !empty($resident['account_expires_at'])?h(date('M d, Y',strtotime($resident['account_expires_at']))):'No expiry' ?></strong><small>Contact the barangay to renew</small></div></div><nav class="portal-tabs" aria-label="Resident services"><a class="<?= $tab==='documents'?'active':'' ?>" href="resident_portal.php?tab=documents">▤ Documents</a><a class="<?= $tab==='report'?'active':'' ?>" href="resident_portal.php?tab=report">▣ Report an issue</a><a class="<?= $tab==='feedback'?'active':'' ?>" href="resident_portal.php?tab=feedback">♡ Feedback</a><a class="<?= $tab==='announcements'?'active':'' ?>" href="resident_portal.php?tab=announcements">◈ Announcements</a></nav>
<?php if($tab==='documents'): ?><section class="panel form-panel"><div class="eyebrow">Document services</div><h2>Request a document</h2><p class="login-copy">Choose the document you need and tell the barangay what it is for.</p><form method="post" enctype="multipart/form-data" class="form-grid single-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="document"><label>Document type<select name="document_type"><option>Barangay clearance</option><option>Certificate of residency</option><option>Certificate of indigency</option><option>Business clearance</option><option>Special certification</option></select></label><label>Purpose<input name="purpose" required placeholder="e.g. Local employment"></label><label>Supporting file (optional)<input type="file" name="attachment" accept="image/jpeg,image/png,application/pdf"><small class="field-help">JPG, PNG, or PDF up to 5 MB.</small></label><button class="primary-button full-button">Submit document request</button></form></section><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">My requests</div><h2>Document tracking</h2></div><span class="muted"><?= count($documents) ?> requests</span></div><div class="portal-list"><?php foreach($documents as $item): ?><div class="portal-row"><div><strong><?= h($item['document_type']) ?></strong><small><?= h($item['request_no']) ?><?php if($item['document_no']): ?> · Official no. <?= h($item['document_no']) ?><?php endif; ?> · <?= h($item['purpose']) ?></small></div><span class="status-pill <?= h(strtolower(str_replace(' ','-',$item['status']))) ?>"><i></i><?= h($item['status']) ?></span></div><?php endforeach; ?><?php if(!$documents): ?><p class="empty-state">You have not submitted a document request yet.</p><?php endif; ?></div></section><?php elseif($tab==='report'): ?><section class="panel form-panel"><div class="eyebrow">Resident reporting</div><h2>Report an issue</h2><p class="login-copy">Choose a category and tell us about the person, office, provider, or group involved or affected.</p><form method="post" enctype="multipart/form-data" class="form-grid single-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="incident"><label>Report category<select name="report_type"><option>Incident report</option><option>Blotter report</option><option>Road issue</option><option>Power outage</option><option>Water interruption</option><option>Garbage collection</option><option>Noise disturbance</option><option>Public safety</option><option>Other concern</option></select></label><label>Date and time<input type="datetime-local" name="incident_date" required value="<?= date('Y-m-d\TH:i') ?>"></label><label>Person involved or affected<input name="respondent" required placeholder="Name of person, office, provider, or group"></label><label>Location<input name="location" required placeholder="Purok / street"></label><label>Evidence file (optional)<input type="file" name="attachment" accept="image/jpeg,image/png,application/pdf"><small class="field-help">JPG, PNG, or PDF up to 5 MB.</small></label><label>Details<textarea name="narrative" rows="4" required placeholder="Describe what happened and who was involved or affected..."></textarea></label><button class="primary-button full-button">Submit report</button></form></section><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">My reports</div><h2>Issue tracking</h2></div><span class="muted"><?= count($incidents) ?> reports</span></div><div class="portal-list"><?php foreach($incidents as $item): ?><div class="portal-row"><div><strong><?= h($item['report_type']) ?></strong><small><?= h($item['case_no']) ?> · <?= h(date('M d, Y',strtotime($item['incident_date']))) ?> · Involved/affected: <?= h($item['respondent']) ?> · <?= h($item['location']) ?></small></div><span class="status-pill <?= h(strtolower(str_replace(' ','-',$item['status']))) ?>"><i></i><?= h($item['status']) ?></span></div><?php endforeach; ?><?php if(!$incidents): ?><p class="empty-state">You have not submitted a report yet.</p><?php endif; ?></div></section><?php elseif($tab==='feedback'): ?><section class="panel form-panel"><div class="card-header"><div><div class="eyebrow">Community listening</div><h2>Send feedback</h2><p class="login-copy">Tell the barangay what is working or what needs improvement.</p></div></div><form method="post" class="form-grid feedback-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="feedback"><label>Feedback category<select name="category"><option>Service experience</option><option>Document request</option><option>Report follow-up</option><option>Announcement</option><option>Suggestion</option></select></label><label>Rating<select name="rating"><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Fair</option><option value="2">2 — Needs improvement</option><option value="1">1 — Poor</option></select></label><label class="wide">Your feedback<textarea name="message" rows="4" required placeholder="Share your experience..."></textarea></label><div class="form-actions"><button class="primary-button">Send feedback</button></div></form></section><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Feedback history</div><h2>My previous feedback</h2></div><span class="muted"><?= count($feedback) ?> submissions</span></div><div class="portal-list feedback-history"><?php foreach($feedback as $item): ?><div class="portal-row"><div><strong><?= h($item['category']) ?> · <?= h($item['rating']) ?>/5</strong><small><?= h($item['message']) ?></small></div><span class="status-pill <?= h(strtolower($item['status'])) ?>"><i></i><?= h($item['status']) ?></span></div><?php endforeach; ?><?php if(!$feedback): ?><p class="empty-state">You have not sent feedback yet.</p><?php endif; ?></div></section><?php else: ?><section class="panel announcement-strip"><div><div class="eyebrow">Latest barangay updates</div><h2><?= h($announcements[0]['title']??'No announcements yet') ?></h2><p><?= h($announcements[0]['body']??'Check back for the latest barangay updates.') ?></p></div></section><div class="announcement-card-grid"><?php foreach($announcements as $announcement): ?><article class="panel announcement-card"><div class="announcement-banner <?= h($announcement['category']??'') ?>"><strong><?= h($announcement['category']??'Announcement') ?></strong><small><?= h(date('M d, Y',strtotime($announcement['published_at']))) ?></small></div><div class="announcement-card-body"><h3><?= h($announcement['title']) ?></h3><p><?= h($announcement['body']) ?></p></div></article><?php endforeach; ?><?php if(!$announcements): ?><p class="empty-state">No published announcements are available.</p><?php endif; ?></div><?php endif; ?><?php require __DIR__.'/partials/footer.php'; ?>
